head.script:
scwin.onpageload = function () {
	var selectBoxObj = [
		{ "label": "A", "value": "A" },
		{ "label": "B", "value": "B" },
		{ "label": "C", "value": "C" },
		{ "label": "D", "value": "D" }
	];
	categoryData.setJSON(selectBoxObj);

	var selectBoxObj2 = [
		{ "subCategoryGubun": "A", "value": "A1", "label": "A중분류-1" },
		{ "subCategoryGubun": "A", "value": "A2", "label": "A중분류-2" },
		{ "subCategoryGubun": "A", "value": "A3", "label": "A중분류-3" },
		{ "subCategoryGubun": "A", "value": "A4", "label": "A중분류-4" },
		{ "subCategoryGubun": "A", "value": "A5", "label": "A중분류-5" },
		{ "subCategoryGubun": "A", "value": "A6", "label": "A중분류-6" },
		{ "subCategoryGubun": "A", "value": "A7", "label": "A중분류-7" },
		{ "subCategoryGubun": "A", "value": "A8", "label": "A중분류-8" },
		{ "subCategoryGubun": "A", "value": "A9", "label": "A중분류-9" },
		{ "subCategoryGubun": "A", "value": "A10", "label": "A중분류-10" },
		{ "subCategoryGubun": "A", "value": "A11", "label": "A중분류-11" },
		{ "subCategoryGubun": "A", "value": "A12", "label": "A중분류-12" },
		{ "subCategoryGubun": "A", "value": "A13", "label": "A중분류-13" },
		{ "subCategoryGubun": "A", "value": "A14", "label": "A중분류-14" },
		{ "subCategoryGubun": "A", "value": "A15", "label": "A중분류-15" }
	];
	subCategoryData.setJSON(selectBoxObj2);

	selectBoxObj2 = [
		{ "subCategoryGubun": "B", "value": "B1", "label": "B중분류-1" },
		{ "subCategoryGubun": "B", "value": "B2", "label": "B중분류-2" }
	];
	subCategoryData2.setJSON(selectBoxObj2);

	selectBoxObj2 = [
		{ "subCategoryGubun": "C", "value": "C1", "label": "C중분류-1" },
		{ "subCategoryGubun": "C", "value": "C2", "label": "C중분류-2" }
	];
	subCategoryData3.setJSON(selectBoxObj2);

	selectBoxObj2 = [
		{ "subCategoryGubun": "D", "value": "D1", "label": "D중분류-1" },
		{ "subCategoryGubun": "D", "value": "D2", "label": "D중분류-2" }
	];
	subCategoryData4.setJSON(selectBoxObj2);

	// selectBoxObj 수 만큼 행 추가
	gridViewData.setJSON(selectBoxObj);
};

// 대분류 선택 시마다 이벤트 실행
scwin.gridView1_onviewchange = function (info) {
	console.log("gridView onviewchange", info);
	if (info.colIndex == 0) {
		var cellObj = {};
		if (info.newValue == "A") {
			cellObj = {
				inputType: "autoComplete",
				options: {
					chooseOption: true,
					chooseOptionLabel: "선택",
					embeddedInput : true
				},
				itemSet: {
					nodeset: "data:subCategoryData",
					label: "label",
					value: "value"
				}
			}
		} else if (info.newValue == "B") {
			cellObj = {
				inputType: "select",
				options: { viewType: "icon",
					embeddedInput : true },
				itemSet: {
					nodeset: "data:subCategoryData2",
					label: "label",
					value: "value"
				}
			}
		} else if (info.newValue == "C") {
			cellObj = {
				inputType: "select",
				options: { viewType: "icon" },
				itemSet: {
					nodeset: "data:subCategoryData3",
					label: "label",
					value: "value"
				}
			}
		} else {
			cellObj = {
				inputType: "select",
				options: { viewType: "icon" },
				itemSet: {
					nodeset: "data:subCategoryData4",
					label: "label",
					value: "value"
				}
			}
		}
		gridView1.setCellInputType(info.rowIndex, "col2", cellObj);
	}
};

scwin.setVal1 = function() {
	let info1 = { colIndex: 0, newValue: "A", colId: "col1", rowIndex: 0, oldValue: "", newSelectedIndex: 1, oldSelectedIndex: 0 };
	scwin.gridView1_onviewchange(info1);
};

scwin.checkVal1 = function() {
	return (document.getElementById('gridView1_dynamic_autoComplete_0_1_input') || document.getElementById('mf_gridView1_dynamic_autoComplete_0_1_input')).value == 'A중분류-1';
};
